{"explanation":"Imagine 1000 people. 10 are sick, and the test catches 9 of them. Of the 990 healthy people, 10% (99) wrongly test positive. So among 108 positive results, only 9 are truly sick, which is 9/108 ≈ 8.3%. The disease is so rare that false positives from the healthy majority swamp the true positives. Use the sliders to change prevalence and accuracy.","manimCode":"let prev = 0.01;
let acc = 0.9;
let objs = [];

function build() {
  for (const o of objs) scene.remove(o);
  objs = [];
  const W = 10, left = -5;
  const sick = prev, healthy = 1 - prev;
  const tp = sick * acc, fp = healthy * (1 - acc);
  const post = tp / (tp + fp);

  const add = (o) => { scene.add(o); objs.push(o); return o; };
  const bar = (x0, w, y, h, col) => {
    const wd = Math.max(w, 0.03);
    const r = new Rectangle({ width: wd, height: h, color: col });
    r.setFill(col, 0.6);
    r.moveTo([x0 + wd / 2, y, 0]);
    return add(r);
  };
  const label = (s, x, y, col, fs) => {
    const t = new Text({ text: s, color: col, fontSize: fs || 22 });
    t.moveTo([x, y, 0]);
    return add(t);
  };

  label('Population: 1000 people', 0, 3.4, WHITE, 24);
  const sw = W * sick;
  bar(left, sw, 2.5, 0.8, RED);
  bar(left + sw, W - sw, 2.5, 0.8, BLUE);
  label('Sick: ' + (sick * 1000).toFixed(0), -3, 1.8, RED, 20);
  label('Healthy: ' + (healthy * 1000).toFixed(0), 2.5, 1.8, BLUE, 20);

  label('Everyone who tests positive: ' + ((tp + fp) * 1000).toFixed(0), 0, 0.7, WHITE, 24);
  const tw = W * tp / (tp + fp);
  bar(left, tw, -0.1, 0.8, RED);
  bar(left + tw, W - tw, -0.1, 0.8, BLUE);
  label('True positives: ' + (tp * 1000).toFixed(0), left + Math.max(tw / 2, 1.2), -0.9, RED, 20);
  label('False positives: ' + (fp * 1000).toFixed(0), left + tw + (W - tw) / 2 + 0.5, -1.5, BLUE, 20);

  label('P(sick | positive) = ' + (post * 100).toFixed(1) + '%', 0, -2.6, YELLOW, 34);
  label('prevalence ' + (prev * 100).toFixed(1) + '%, accuracy ' + (acc * 100).toFixed(0) + '%', 0, -3.3, GRAY, 18);
}

build();

const controls = new Controls(scene, { position: 'bottom-left' });
controls.addSlider({ label: 'Prevalence %', min: 0.1, max: 50, value: 1, step: 0.1, onChange: (v) => { prev = v / 100; build(); } });
controls.addSlider({ label: 'Accuracy %', min: 50, max: 99, value: 90, step: 1, onChange: (v) => { acc = v / 100; build(); } });

await scene.wait(999999);"}

